// Advanced Normalize
function normalize(str) {
  return (str || "")
    .toString()
    .toLowerCase()
    .replace(/[^a-z0-9 ]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

//  Synonym Dictionary
const synonyms = {
  laptop: ["notebook"],
  notebook: ["laptop"],
  mouse: ["pointer"],
  printer: ["printing"],
};

//  Expand tokens with synonyms
function expandTokens(tokens) {
  const expanded = new Set(tokens);

  tokens.forEach(token => {
    if (synonyms[token]) {
      synonyms[token].forEach(s => expanded.add(s));
    }
  });

  return [...expanded];
}

//  Token similarity (Jaccard)
function getTokenSimilarity(a, b) {
  if (!a || !b) return 0;

  let tokensA = expandTokens(a.split(" "));
  let tokensB = expandTokens(b.split(" "));

  const setA = new Set(tokensA);
  const setB = new Set(tokensB);

  const intersection = [...setA].filter(x => setB.has(x));
  const union = new Set([...setA, ...setB]);

  return union.size === 0 ? 0 : intersection.length / union.size;
}

//  Levenshtein similarity
function getLevenshteinSimilarity(a, b) {
  if (!a || !b) return 0;

  const matrix = [];
  for (let i = 0; i <= b.length; i++) matrix[i] = [i];
  for (let j = 0; j <= a.length; j++) matrix[0][j] = j;

  for (let i = 1; i <= b.length; i++) {
    for (let j = 1; j <= a.length; j++) {
      matrix[i][j] = b[i - 1] === a[j - 1]
        ? matrix[i - 1][j - 1]
        : Math.min(
            matrix[i - 1][j - 1] + 1,
            matrix[i][j - 1] + 1,
            matrix[i - 1][j] + 1
          );
    }
  }

  const distance = matrix[b.length][a.length];
  const maxLen = Math.max(a.length, b.length);

  return maxLen === 0 ? 1 : (maxLen - distance) / maxLen;
}

//  Hybrid similarity
function getHybridSimilarity(a, b) {
  const tokenSim = getTokenSimilarity(a, b);
  const levSim = getLevenshteinSimilarity(a, b);
  return Math.max(tokenSim, levSim);
}

//  Load Data
const invoicesRaw = $items("fetch invoice data").map(i => i.json);
const posRaw = $items("Fetch Purchase Order").map(i => i.json);
const grnsRaw = $items("fetch good receipt").map(i => i.json);

//  Clean & prepare data
const invoices = invoicesRaw
  .filter(i => i.status === "pending" && Number(i.invoice_amount) > 0)
  .map(i => ({
    invoice_id: (i.invoice_id || "").trim(),
    vendor_id: (i.vendor_id || "").trim(),
    invoice_amount: Number(i.invoice_amount),
    invoice_items: normalize(i.items)
  }));

const pos = posRaw.map(p => ({
  po_id: p.po_id,
  vendor_id: (p.vendor_id || "").trim(),
  po_amount: Number(p.po_amount),
  po_items: normalize(p.items)
}));

const grns = grnsRaw.map(g => ({
  grn_id: g.grn_id,
  po_id: g.po_id,
  received_amount: Number(g.received_amount),
  grn_items: normalize(g.items)
}));

//  Matching + Scoring
const results = [];

for (const inv of invoices) {

  const matchingPOs = pos.filter(p => p.vendor_id === inv.vendor_id);

  //  Case 1: No PO found
  if (matchingPOs.length === 0) {
    results.push({
      json: {
        ...inv,
        po_id: null,
        grn_id: null,
        po_amount: null,
        received_amount: null,
        po_items: null,
        grn_items: null,
        poDiff: null,
        grnDiff: null,
        similarity: 0,
        itemMatchStatus: "none",
        matchScore: 0,
        reason: "No matching PO found"
      }
    });
    continue;
  }

  for (const po of matchingPOs) {

    const matchingGRNs = grns.filter(g => g.po_id === po.po_id);

    //  Case 2: No GRN found
    if (matchingGRNs.length === 0) {
      results.push({
        json: {
          ...inv,
          po_id: po.po_id,
          grn_id: null,
          po_amount: po.po_amount,
          received_amount: null,
          po_items: po.po_items,
          grn_items: null,
          poDiff: Math.abs(inv.invoice_amount - po.po_amount),
          grnDiff: null,
          similarity: 0,
          itemMatchStatus: "none",
          matchScore: 0,
          reason: "No matching GRN found"
        }
      });
      continue;
    }

    for (const grn of matchingGRNs) {

      const poDiff = Math.abs(inv.invoice_amount - po.po_amount);
      const grnDiff = Math.abs(inv.invoice_amount - grn.received_amount);
      const tolerance = inv.invoice_amount * 0.05;

      const invPoSim = getHybridSimilarity(inv.invoice_items, po.po_items);
      const poGrnSim = getHybridSimilarity(po.po_items, grn.grn_items);
      const avgSim = (invPoSim + poGrnSim) / 2;

      let itemMatchStatus;

      if (avgSim >= 0.95) {
        itemMatchStatus = "full";
      } else if (avgSim >= 0.7) {
        itemMatchStatus = "partial";
      } else {
        itemMatchStatus = "none";
      }

      let score = 100;

      if (poDiff > tolerance) score -= 20;
      if (grnDiff > tolerance) score -= 20;

      if (avgSim < 0.95 && avgSim >= 0.85) score -= 5;

      if (itemMatchStatus === "partial") score -= 10;
      if (itemMatchStatus === "none") score -= 30;

      results.push({
        json: {
          ...inv,
          po_id: po.po_id,
          grn_id: grn.grn_id,
          po_amount: po.po_amount,
          received_amount: grn.received_amount,
          po_items: po.po_items,
          grn_items: grn.grn_items,
          poDiff,
          grnDiff,
          similarity: Number(avgSim.toFixed(2)),
          itemMatchStatus,
          matchScore: Math.max(0, Math.round(score))
        }
      });
    }
  }
}

return results;

//  Group by invoice
const grouped = {};

for (const item of items) {
  const d = item.json;

  if (!grouped[d.invoice_id]) {
    grouped[d.invoice_id] = [];
  }

  grouped[d.invoice_id].push(d);
}

//  Pick best match ONLY (no re-scoring)
const results = [];

for (const invId in grouped) {
  const matches = grouped[invId];

  matches.sort((a, b) => b.matchScore - a.matchScore);

  const best = matches[0];

  results.push({
    json: {
      ...best,
      selected: true
    }
  });
}

return results;

