const originalItems = $items("Retain Original Transaction Data");

return items.map((item, index) => {
  const text = (item.json.text || "").toLowerCase();

  const original = originalItems[index]?.json || {};

  return {
    json: {
      ...original,
      semantic_result: text.includes("yes") ? "yes" : "no"
    }
  };
});

// Use ONLY current branch items (important fix)
const switchData = $items("Flag: Route to Forensic AI Audit");

//  Notion data (already coming into this node)
let notionData = items.map(i => i.json || {});



return switchData.map((swItem) => {

  const currentInvoiceId = swItem.json.invoice_id;
  const currentVendor = (swItem.json.vendor_id || "").trim();

  //  Filter same vendor + exclude current invoice
  let filtered = notionData.filter(n => {
    const vendor = (n.property_vendor_id || "").trim();
    const invId = n.property_invoice_id || "";

    return vendor === currentVendor && invId !== currentInvoiceId;
  });

  //  Deduplicate
  const uniqueMap = {};
  filtered.forEach(n => {
    const key = n.property_invoice_id;
    if (key && !uniqueMap[key]) {
      uniqueMap[key] = n;
    }
  });

  const uniqueData = Object.values(uniqueMap);

  //  Build history
  let historyText = "No past approvals found.";

  if (uniqueData.length > 0) {
    historyText = uniqueData.map((a, idx) => {
      return `Case ${idx + 1}:
Invoice: ${a.property_invoice_id || "N/A"}
Score: ${a.property_match_score ?? "N/A"}
Decision: ${a.property_decision || "N/A"}
Reason: ${a.property_reason || "N/A"}`;
    }).join("\n\n");
  }

  return {
    json: {
      ...swItem.json,
      past_approvals: historyText
    }
  };
});

parameters.text:
=Analyze this transaction:

Invoice:
- Amount: {{$json.invoice_amount}}
- Item: {{$json.invoice_items}}

Purchase Order:
- Amount: {{$json.po_amount}}
- Item: {{$json.po_items}}

Goods Receipt:
- Amount: {{$json.received_amount}}
- Item: {{$json.grn_items}}

Match Score: {{$json.matchScore}}

Historical Vendor Data:
{{$json.past_approvals}}

Instructions:
1. Compare Invoice, PO, and GRN items (are they the same product or different category?)
2. Calculate exact amount differences and percentage variance
3. Check if the difference is within 5% tolerance
4. Use historical vendor data only if the product category matches
5. If product category differs → treat as high risk regardless of history

Return ONLY JSON.

parameters.jsCode:
return items.map((item, index) => {
  const originalAI = item.json;

  //  Get matching original item using SAME index
  const original = $items("Flag: Route to Forensic AI Audit")[index]?.json || {};

  //  Extract raw AI response
  let raw =
    originalAI.output ||
    originalAI.message?.content ||
    originalAI.choices?.[0]?.message?.content ||
    "";

  raw = raw
    .replace(/```json/g, "")
    .replace(/```/g, "")
    .trim();

  let ai;

  try {
    ai = JSON.parse(raw);
  } catch (e) {
    ai = {
      reason: "Failed to parse AI response",
      severity: "medium",
      decision: "review"
    };
  }

  //  Normalize
  let severity = (ai.severity || "medium").toLowerCase();
  let decision = (ai.decision || "review").toLowerCase();

  //  enforce consistency
  if (severity === "high") decision = "rejected";
  if (severity === "low") decision = "approved";

  return {
    json: {
      //  TAKE DATA FROM "Create Data For AI"
      invoice_id: original.invoice_id,
      vendor_id: original.vendor_id,
      matchScore: original.matchScore,

      //  AI output
      reason: ai.reason || "No reason provided",
      severity,
      decision
    }
  };
});
